#!/usr/bin/env python3
import os
import subprocess
import base64
import tarfile
import io

print("=== AGGIORNAMENTO SONG (maestro-studio) ===")
APP_DIR = "/var/www/maestro-studio"
os.makedirs(APP_DIR, exist_ok=True)
os.chdir(APP_DIR)

print("[1/4] Ricostruzione archivio dai chunk...")
chunks = ['', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '']

b64_data = "".join(chunks)
tar_bytes = base64.b64decode(b64_data)

print("[2/4] Estrazione file di produzione (server.js e dist)...")
with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:gz") as tar:
    tar.extractall(path=".")

print("[3/4] Configurazione dipendenze e pacchetti...")
package_json = """{
  "name": "maestro-studio",
  "version": "1.0.0",
  "type": "module",
  "dependencies": {
    "@google/genai": "^2.4.0",
    "dotenv": "^17.2.3",
    "express": "^4.21.2"
  }
}"""

with open("package.json", "w") as f:
    f.write(package_json)

subprocess.run(["npm", "install", "--production"], check=True)

print("[4/4] Configurazione Nginx e PM2 (Preserva porte e sottodomini)...")
nginx_conf = "/etc/nginx/sites-available/freeserv"
if os.path.exists(nginx_conf):
    with open(nginx_conf, "r") as f:
        content = f.read()
    
    song_block = """
    # App Song sulla porta 5000
    location /Song {
        proxy_pass http://127.0.0.1:5000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;
    }
    location /song {
        proxy_pass http://127.0.0.1:5000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;
    }
"""
    if "location /Song" not in content and "server_name freeserv.it" in content:
        idx = content.find("server_name freeserv.it")
        brace_idx = content.find("}", idx)
        if brace_idx != -1:
            content = content[:brace_idx] + song_block + "\n" + content[brace_idx:]
            with open(nginx_conf, "w") as f:
                f.write(content)
            print("Nginx patched successfully.")

try:
    subprocess.run(["sudo", "ln", "-sf", nginx_conf, "/etc/nginx/sites-enabled/"], check=True)
    subprocess.run(["sudo", "nginx", "-t"], check=True)
    subprocess.run(["sudo", "systemctl", "restart", "nginx"], check=True)
except Exception as e:
    print("Nota Nginx/sudo:", e)

if subprocess.run(["which", "pm2"], stdout=subprocess.DEVNULL).returncode != 0:
    try:
        subprocess.run(["sudo", "npm", "install", "-g", "pm2"], check=True)
    except:
        pass

try:
    subprocess.run(["pm2", "kill"], check=True)
except:
    pass

if os.path.exists(os.path.expanduser("~/.pm2/dump.pm2")):
    try:
        os.remove(os.path.expanduser("~/.pm2/dump.pm2"))
    except:
        pass

env = os.environ.copy()
env["PORT"] = "5000"
subprocess.run(["pm2", "start", "server.js", "--name", "maestro-studio", "--cwd", APP_DIR], env=env, check=True)
subprocess.run(["pm2", "save"], check=True)

print("=== AGGIORNAMENTO COMPLETATO CON SUCCESSO! ===")
print("Visita: http://freeserv.it/Song")
